# PDF Document Extraction with pdf.js

Here's the complete source code from the example:

```javascript
/* Any copyright is dedicated to the Public Domain.
 * http://creativecommons.org/publicdomain/zero/1.0/ */

import { getDocument } from "pdfjs-dist/legacy/build/pdf.mjs";

const pdfPath =
  process.argv[2] || "../../web/compressed.tracemonkey-pldi-09.pdf";

const loadingTask = getDocument({ url: pdfPath });
try {
  const pdfDoc = await loadingTask.promise;

  const { numPages } = pdfDoc;
  console.log("# Document Loaded");
  console.log(`Number of Pages: ${numPages}`);
  console.log();

  const { info, metadata } = await pdfDoc.getMetadata();
  console.log("# Metadata is Loaded");
  console.log("## Info");
  console.log(JSON.stringify(info, null, 2));
  console.log();
  if (metadata) {
    console.log("## Metadata");
    console.log(JSON.stringify(Object.fromEntries(metadata), null, 2));
    console.log();
  }

  for (let i = 1; i <= numPages; i++) {
    const pdfPage = await pdfDoc.getPage(i);
    console.log(`# Page ${i}`);
    const viewport = pdfPage.getViewport({ scale: 1.0 });
    console.log(`Size: ${viewport.width}x${viewport.height}`);
    console.log();

    const { items } = await pdfPage.getTextContent();
    console.log("## Text Content");
    console.log(items.map(item => item.str).join(" "));
    console.log();
    pdfPage.cleanup();
  }

  await loadingTask.destroy();
  console.log("# End of Document");
} catch (ex) {
  console.error(`Error: ${ex}`);
}
```

**Key aspects:** This Node.js script uses the legacy build distribution, employs async/await for promise handling, extracts text via `getTextContent()`, and properly releases resources.
